<script setup>
import {computed,onMounted,ref} from 'vue';
import {RouterLink} from 'vue-router';
import {api} from '../api';
import {session} from '../session';
import {date,label} from '../domain';
import {shortId,roleLabel,dashboardCardLink,hasPermission,ADMIN_REPORTS_PATH,ADMIN_REPORTS_TITLE} from '../workspace';
import AppIcon from '../components/AppIcon.vue';
import FetchState from '../components/FetchState.vue';
import WorkspaceStatus from '../components/WorkspaceStatus.vue';
const data=ref(null),busy=ref(false),error=ref(null);
const admin=computed(()=>session.user?.role==='ADMIN');
const cards=computed(()=>{const n=data.value?.counts||{};return (admin.value?[
  ['official','Laporan resmi','Seluruh laporan yang sudah dikirim','reports'],['unassigned','Belum ditugaskan','Memerlukan penanggung jawab','clipboard'],
  ['operators','Operator aktif','Akun aktif dan terverifikasi','users'],['closed','Laporan ditutup','Riwayat tetap tersedia','check']]:[
  ['queue','Antrean dapat diklaim','Laporan tanpa penanggung jawab','reports'],['assigned','Dalam penanganan','Laporan yang Anda tangani','clipboard'],
  ['review_pending','Perlu direview','Menunggu pemeriksaan petugas','eye'],['followup_pending','Tindak lanjut tertunda','Belum ada tindak lanjut tertunda','clock']])
  .map(([key,title,caption,icon])=>({key,title,caption,icon,value:n[key],unit:key==='operators'?'akun':'laporan',to:n[key]===undefined?null:dashboardCardLink(session.user,key),action:{official:'Lihat laporan resmi',unassigned:'Lihat belum ditugaskan',operators:'Lihat Operator aktif',closed:'Lihat laporan ditutup',queue:'Buka antrean',assigned:'Lihat penanganan',review_pending:'Buka daftar review',followup_pending:'Lihat tindak lanjut'}[key]}));});
const scopeTo=computed(()=>({queue:'/workspace/queue',assigned:'/workspace/assigned',monitor:ADMIN_REPORTS_PATH,assignment:ADMIN_REPORTS_PATH}[data.value?.scope]));
const scopeAction=computed(()=>['monitor','assignment'].includes(data.value?.scope)?ADMIN_REPORTS_TITLE:data.value?.scope==='queue'?'Buka antrean':'Penanganan Saya');
async function load(){busy.value=true;error.value=null;try{data.value=(await api('workspace/dashboard/')).data;}catch(e){error.value=e;data.value=null;}finally{busy.value=false;}}
onMounted(load);
</script>
<template>
  <div class="page-heading ws-page-heading"><div><div class="eyebrow">RUANG {{ roleLabel(session.user?.role).toUpperCase() }}</div><h1>Dashboard {{ roleLabel(session.user?.role) }}</h1><p class="subtitle">{{ admin?'Pantau laporan resmi, penugasan, dan kesiapan akun Operator.':'Tinjau antrean dan ikuti laporan yang menjadi tanggung jawab Anda.' }}</p></div><button :disabled="busy" @click="load"><AppIcon name="refresh" :size="15" />Muat ulang</button></div>
  <p v-if="$route.query.denied" class="notice warning">Halaman tersebut memerlukan kewenangan yang belum diberikan kepada akun Anda.</p>
  <section class="ws-hero"><div><div class="eyebrow">RUANG KERJA {{ roleLabel(session.user?.role).toUpperCase() }}</div><h2>{{ admin?'Pantau laporan, jaga penanganan tetap terarah.':'Setiap laporan, tindak lanjut terarah.' }}</h2><p>{{ admin?'Ikuti laporan resmi dan pastikan penanggung jawabnya tersedia.':'Tinjau ringkasan resmi, tangani sesuai penugasan, dan catat perkembangan laporan.' }}</p><div class="ws-hero-actions"><RouterLink v-if="scopeTo" class="button primary" :to="scopeTo"><AppIcon name="arrow" :size="17" />{{ scopeAction }}</RouterLink><RouterLink v-if="!admin&&scopeTo!=='/workspace/assigned'&&hasPermission(session.user,'view_assigned_report')" class="ws-hero-secondary" to="/workspace/assigned">Penanganan Saya</RouterLink></div></div><div class="ws-hero-art" aria-hidden="true"><div class="ws-document"><AppIcon name="reports" :size="28" /><strong>LAPORAN RESMI</strong><i/><i/><div><b>Tercatat. Tertangani.</b><small>Pelayanan yang lebih baik.</small></div><i/></div><span><AppIcon name="check" :size="28" /></span></div></section>
  <FetchState v-if="busy" title="Memuat ringkasan ruang kerja…" description="Membaca laporan dan aktivitas sesuai kewenangan akun." /><FetchState v-else-if="error" state="error" title="Ringkasan belum dapat dimuat" description="Coba lagi untuk membaca keadaan terbaru." :error="error" :disabled="busy" @retry="load" />
  <div v-if="!error" class="ws-stat-grid"><component :is="card.to?RouterLink:'section'" v-for="(card,index) in cards" :key="card.key" :to="card.to||undefined" class="ws-stat ws-metric card" :class="['ws-metric-'+index,{'ws-metric-link':card.to}]" :aria-label="card.to?card.title+': '+card.value+' '+card.unit+'. '+card.action:undefined"><div><span>{{ card.title }}</span><span class="ws-stat-icon" :class="'accent-'+index"><AppIcon :name="card.icon" :size="21" /></span></div><strong>{{ card.value??'—' }}</strong><small>{{ card.value===undefined?(busy?'Menunggu respons':'Memerlukan izin terkait'):card.key==='followup_pending'&&card.value>0?'Memerlukan tindak lanjut':card.caption }}</small><span v-if="card.to" class="ws-metric-action">{{ card.action }}<AppIcon name="arrow" :size="17" /></span></component></div>
  <div v-if="data&&!busy&&!error" class="ws-dashboard-grid"><section class="card ws-table-panel"><header class="ws-panel-heading"><div><h2>{{ admin?'Laporan terbaru':'Laporan resmi terbaru' }}</h2><p>Ringkasan laporan dalam kewenangan Anda.</p></div><RouterLink v-if="scopeTo" :to="scopeTo" class="ws-text-link">Lihat semua <AppIcon name="arrow" :size="14" /></RouterLink></header>
    <div v-if="!busy&&!data?.reports?.length" class="empty"><AppIcon name="reports" :size="36" /><h3>Belum ada laporan resmi</h3><p>Laporan akan muncul setelah Reporter mengirim versi resminya dan sesuai izin akun Anda.</p></div>
    <div v-else class="ws-table-scroll"><table class="ws-table"><thead><tr><th>ID laporan</th><th>Kategori</th><th>Status</th><th>{{ data?.scope==='queue'?'Aksi':'Penanggung jawab' }}</th></tr></thead><tbody><tr v-for="report in data?.reports||[]" :key="report.id"><td><RouterLink v-if="data?.scope!=='queue'" :to="admin?{path:ADMIN_REPORTS_PATH,query:{laporan:report.id}}:'/workspace/reports/'+report.id">{{ shortId(report.id) }}</RouterLink><strong v-else>{{ shortId(report.id) }}</strong><small>{{ date(report.submitted_at) }}</small></td><td>{{ label(report.event_type) }}</td><td><WorkspaceStatus :value="report.workflow_status" /></td><td><RouterLink v-if="data?.scope==='queue'" class="ws-text-link" to="/workspace/queue">Buka antrean</RouterLink><span v-else>{{ report.operator_name||'Belum ditugaskan' }}</span></td></tr></tbody></table></div>
    <p class="ws-panel-foot"><AppIcon name="shield" :size="15" />Detail privat hanya tersedia sesuai penugasan dan izin.</p>
  </section><aside class="ws-dashboard-aside"><section class="card ws-activity"><h2>Aktivitas terkini</h2><p v-if="!data?.activities?.length" class="muted ws-activity-empty"><AppIcon name="history" :size="21" />Belum ada pembaruan untuk akun ini.</p><ol><li v-for="item in data?.activities||[]" :key="item.id"><span class="heading-icon"><AppIcon name="bell" :size="17" /></span><div><p>{{ item.message }}</p><small>{{ date(item.created_at) }}</small></div></li></ol><RouterLink class="ws-text-link" to="/notifications"><AppIcon name="arrow" :size="14" />Lihat notifikasi</RouterLink><p v-if="!admin" class="fine ws-activity-guidance">Buka rincian untuk membaca status terbaru sebelum melakukan tindakan.</p></section><section v-if="!admin" class="card ws-access-note"><AppIcon name="shield" :size="20" /><div><strong>Akses sesuai izin</strong><p>Klaim dan penugasan menentukan laporan yang dapat Anda tangani. Hak administratif tidak otomatis menjadi hak tindakan Operator.</p></div></section></aside></div>
</template>
